/* Reviewed content adapter: existing device records and routes remain compatible. */
'use strict';
const FACULTY=window.YIHU_FACULTY;
const facultyRecord=id=>FACULTY.find(r=>r.id===id);
const facultyRoute=r=>({KT:'lesson',QA:'faq',AL:'case',LJ:'guide'}[r.kind])+'/'+r.id;
const facultyText=text=>esc(text).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');
const facultyCategory={KT:'反诈课堂',QA:'常见问答',AL:'典型案例',LJ:'维权路径'};
let faqExpanded=false;
const topicKeywords={QA01:['被骗','诈骗','报警'],QA02:['证据','转账','聊天','材料'],QA03:['网购','收货','快递','没收到','未收到','没到货','不发货','未发货','不送货','一直不到','货没到','不退钱','退款'],QA04:['理财','提现','投资'],QA05:['保健品','投诉'],QA06:['援助','免费律师','请不起律师','没钱请律师'],QA07:['诉讼费','减免','缓交','打官司没钱','没钱打官司','交不起'],QA08:['子女','代理','起诉手续'],QA09:['公益','线索'],QA10:['支持起诉','检察院']};
M.lessons=FACULTY.filter(r=>r.kind==='KT').map(r=>({...r,icon:'shield',topic:'防骗知识',...r.quiz}));
M.faqs=FACULTY.filter(r=>r.kind==='QA').map(r=>({...r,question:r.title,keywords:topicKeywords[r.id]||[],answer:r.sections[0].text}));
M.cases=FACULTY.filter(r=>r.kind==='AL').map(r=>({...r,type:{AL01:'诈骗疑虑',AL02:'投资理财',AL03:'消费合同'}[r.id],publisher:r.sourceName,date:''}));
window.YIHU_CONTENT.categories=['全部',...Object.values(facultyCategory)];
window.YIHU_CONTENT.articles=FACULTY.map(r=>({...r,category:facultyCategory[r.kind],label:facultyCategory[r.kind],minutes:'约 '+Math.max(2,Math.ceil(r.sections.map(s=>s.text).join('').length/350))+' 分钟',icon:r.kind==='LJ'?'scale':'book',color:'sage',status:'已审核'}));
function facultyCards(records){return records.length?`<div class="module-list">${records.map(r=>`<button class="module-card" data-go="${facultyRoute(r)}"><span><small>${facultyCategory[r.kind]}</small><strong>${esc(r.title)}</strong><span>${esc(r.summary)}</span></span>${icon('chevron')}</button>`).join('')}</div>`:'<div class="empty"><p>暂未找到匹配内容，可换个关键词或咨询专业人员。</p></div>';}
function facultyBody(r){return `<article class="article-body faculty-article"><span class="label">${facultyCategory[r.kind]}</span><p class="faculty-lead"><strong>${facultyText(r.summary)}</strong></p>${r.sections.map(s=>`<section><h2>${esc(s.heading)}</h2><p class="preserve-text">${facultyText(s.text)}</p></section>`).join('')}${r.images.length?`<section><h2>配图阅读</h2><p>点击图片可放大查看，插图用于情景说明。</p>${r.images.map((im,i)=>`<figure class="article-figure"><button class="image-zoom" data-faculty-image="${r.id}:${i}" aria-label="放大：${esc(im.alt)}"><img src="${im.src}" alt="${esc(im.alt)}" loading="lazy"></button><figcaption>情景示意 · ${i+1}/${r.images.length}</figcaption></figure>`).join('')}</section>`:''}<div class="source-row">${sourceLink(r.source,r.sourceName+' · 查看原文')}</div><p class="field-hint">具体情况可能影响适用。本文不代表机构受理，也不保证个案处理结果。</p></article>`;}
function facultyQuiz(l){return l.quiz?`<form class="form-panel" id="quiz-form" data-lesson="${l.id}"><h2>想一想</h2><fieldset class="answer-options"><legend>${esc(l.quiz.question)}</legend>${l.quiz.choices.map((c,i)=>`<label><input type="radio" name="answer" value="${i}" required><span>${esc(c)}</span></label>`).join('')}</fieldset><button class="primary" type="submit">检查答案</button><p id="quiz-feedback" class="quiz-feedback" role="status"></p></form>`:'';}
lessonPage=function(id){const r=facultyRecord(id)||facultyRecord({call:'KT03',auction:'KT02',family:'KT05'}[id]);return r?back('classroom','返回反诈课堂')+heading(r.title)+facultyBody(r)+facultyQuiz(r)+'<button class="primary" data-go="risk">遇到类似情况，梳理一下</button>':back('classroom')+heading('课堂未找到');};
faqPage=function(id){const r=facultyRecord(id)||facultyRecord({fraud:'QA01',evidence:'QA02',cost:'QA07',child:'QA08',public:'QA09',consumer:'QA05',aid:'QA06'}[id]);return r?back('ask','返回问法')+heading(r.title)+facultyBody(r)+'<div class="actions"><button class="primary" data-go="ask">向 AI 继续提问</button><button class="secondary" data-go="path">查看维权路径</button></div>':back('ask')+heading('问题暂未收录');};
function faqMatches(query){const q=query.replace(/[\s，。！？、,.!?]/g,'').toLowerCase();return M.faqs.map(r=>{const hits=[r.title,...r.keywords].filter(k=>q.includes(k.toLowerCase())||k.toLowerCase().includes(q));return {record:r,score:hits.reduce((n,k)=>n+Math.min(k.length,12),0)};}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).map(x=>x.record);}
faqResults=function(){const q=faqSearch.trim(),rows=q?faqMatches(q):M.faqs;if(!rows.length)return '<div class="empty"><h3>暂未找到相关问答</h3><p>试试“收货”“被骗”“诉讼费”等关键词，或把完整问题交给 AI。</p><button class="primary" data-faq-ai>带着这个问题问 AI</button><button class="secondary" data-go="consultations">申请人工咨询</button></div>';return facultyCards(!q&&!faqExpanded?rows.slice(0,3):rows)+(!q?`<button class="text-btn" data-faq-expand aria-expanded="${faqExpanded}">${faqExpanded?'收起问答':'查看全部 '+rows.length+' 条问答'}</button>`:'');};
document.addEventListener('click',e=>{if(e.target.closest('[data-faq-expand]')){faqExpanded=!faqExpanded;$('#faq-results').innerHTML=faqResults();}if(e.target.closest('[data-faq-ai]')){aiDraft=faqSearch;const field=$('#ai-question-form textarea');field.value=aiDraft;field.focus();field.scrollIntoView({block:'center',behavior:'smooth'});}});
casePage=function(id){const r=facultyRecord(id);return r?back('cases','返回案例库')+heading(r.title)+facultyBody(r)+'<button class="primary" data-go="evidence">整理自己的材料</button>':back('cases')+heading('案例未找到');};
casesPage=function(){return moduleIntro('典型案例库','了解真实案例，认识常见风险与求助方式。')+`<label class="search-wrap">${icon('search')}<input id="case-search" type="search" value="${esc(caseSearch)}" aria-label="搜索案例" placeholder="搜标题或案例关键词"></label><div class="chips">${['全部','诈骗疑虑','投资理财','消费合同'].map(t=>`<button class="chip ${caseFilter===t?'active':''}" data-case-filter="${t}">${t}</button>`).join('')}</div><div id="case-results">${caseResults()}</div>`;};
caseResults=function(){return facultyCards(M.cases.filter(r=>(caseFilter==='全部'||r.type===caseFilter)&&(r.title+r.summary).includes(caseSearch.trim())));};
const originalModulesView=modulesView;
modulesView=function(){if(route.startsWith('guide/')){const r=facultyRecord(route.split('/')[1]);return r?back('path','返回维权路径')+heading(r.title)+facultyBody(r)+'<button class="primary" data-go="evidence">准备自己的材料</button>':back('path')+heading('路径未找到');}return originalModulesView();};
const originalPathPage=pathPage;
pathPage=function(type){return originalPathPage(type)+heading('四份维权路径说明','根据实际情况了解适用条件。')+facultyCards(FACULTY.filter(r=>r.kind==='LJ'));};
document.addEventListener('click',e=>{const b=e.target.closest('[data-faculty-image]');if(!b)return;const [id,n]=b.dataset.facultyImage.split(':'),im=facultyRecord(id)?.images[Number(n)];if(im)modal('放大查看配图',`<div class="image-scroll"><img src="${im.src}" alt="${esc(im.alt)}"></div><p>可横向滚动查看细节。</p>`);});
